from tools.slacktesterbot.slacktester.scenarios.base import BaseScenario, TestCase

class WorkbinderScenario(BaseScenario):
    name = 'workbinder'
    description = 'Workbinder subcommand parsing'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='workbinder_list', command='workbinder list', expected={'error': False, 'parse_result': {'subcommand': 'list', 'limit': 50}}, description='Workbinder list subcommand'), TestCase(name='workbinder_list_with_limit', command='workbinder list limit=5', expected={'error': False, 'parse_result': {'subcommand': 'list', 'limit': 5}}, description='Workbinder list with limit'), TestCase(name='workbinder_show', command='workbinder show run_12345', expected={'error': False, 'parse_result': {'subcommand': 'show', 'binder_id': 'run_12345'}}, description='Workbinder show specific binder'), TestCase(name='workbinder_artifacts', command='workbinder artifacts run_12345', expected={'error': False, 'parse_result': {'subcommand': 'artifacts', 'binder_id': 'run_12345'}}, description='Workbinder artifacts for binder'), TestCase(name='workbinder_artifact', command='workbinder artifact art_abc123', expected={'error': False, 'parse_result': {'subcommand': 'artifact', 'binder_id': 'art_abc123'}}, description='Workbinder specific artifact'), TestCase(name='workbinder_search', command='workbinder search binder123 "timeout error"', expected={'error': False, 'parse_result': {'subcommand': 'search', 'binder_id': 'binder123', 'query': 'timeout error'}}, description='Workbinder search with query'), TestCase(name='workbinder_history', command='workbinder history run_12345', expected={'error': False, 'parse_result': {'subcommand': 'history', 'binder_id': 'run_12345'}}, description='Workbinder history for binder'), TestCase(name='workbinder_audit', command='workbinder audit run_12345', expected={'error': False, 'parse_result': {'subcommand': 'audit', 'binder_id': 'run_12345'}}, description='Workbinder audit for binder'), TestCase(name='workbinder_no_subcommand', command='workbinder', expected={'error': False, 'parse_result': {'subcommand': 'help'}}, description='Workbinder without subcommand defaults to help')]